/// Group of all the possible operations related to collection aliases
#[derive(Debug, Deserialize, Serialize, JsonSchema, PartialEq, Eq, Hash, Clone)]
#[serde(rename_all = "snake_case")]
#[serde(untagged)]                          // <- first matching variant wins; extra keys silently dropped
pub enum AliasOperations {
    CreateAlias(CreateAliasOperation),
    DeleteAlias(DeleteAliasOperation),
    RenameAlias(RenameAliasOperation),
}
...
/// Alias changes are atomic, meaning that no collection modifications can happen between
/// alias operations.
pub struct ChangeAliasesOperation {
    pub actions: Vec<AliasOperations>,
}

// src/actix/api/collections_api.rs L180-196
#[post("/collections/aliases")]
async fn update_aliases(
    dispatcher: web::Data<Dispatcher>,
    operation: Json<ChangeAliasesOperation>,   // plain actix Json extractor; no Valid<> validator, no .validate() call on this path
    Query(query): Query<WaitTimeout>,
    ActixAuth(auth): ActixAuth,
) -> impl Responder {
    let response = dispatcher
        .submit_collection_meta_op(
            CollectionMetaOperations::ChangeAliases(operation.0), ...)
        .await;
    process_response(response, timing, None)
}

// lib/storage/src/content_manager/toc/collection_meta_ops.rs L299-338 (application loop)
async fn update_aliases(&self, operation: ChangeAliasesOperation) -> Result<bool, StorageError> {
    let collection_lock = self.collections.write().await;
    let mut alias_lock = self.alias_persistence.write().await;
    for action in operation.actions {          // elements already deserialized to exactly one variant
        match action {
            AliasOperations::CreateAlias(CreateAliasOperation { create_alias: CreateAlias { collection_name, alias_name } }) => {
                collection_lock.validate_collection_exists(&collection_name)?;   // source of the documented 404
                collection_lock.validate_collection_not_exists(&alias_name)?;
                alias_lock.insert(alias_name, collection_name)?;
            }
            AliasOperations::DeleteAlias(...) => { alias_lock.remove(&alias_name)?; }
            AliasOperations::RenameAlias(...) => { alias_lock.rename_alias(&old_alias_name, new_alias_name)?; }
        };
    }
    Ok(true)
}

